class AutomatedTellerMachineSystem_AutoGenerated {
  /*SystemVariable Start*/
  PasswordValidated: boolean;
  WithdrawedNumber: number;
  InputCard: BankCard;
  CardIDValidated: boolean;
  IsDeposit: boolean;
  IsWithdraw: boolean;
  DepositedNumber: number;
  /*SystemVariable End*/

  /*the card id and password is validated and the input card exist, then if the money is withdraw,
   *if print the withdrawed number or if it is deposit print the deposited number or print 0*/
  printReceipt(): number {
    /*Definition Start*/
    let selectedCard: BankCard = l({
      logic: () =>
        getRepository(BankCard).find(
          (c: any) =>
            l({
              logic: () => c.CardID === this.InputCard.CardID,
              description: "c.CardID=self.InputCard.CardID",
            })
              .and({
                logic: () => c.Password === this.InputCard.Password,
                description: "c.Password=self.InputCard.Password",
              })
              .build().pass,
        ),
      description:
        "BankCard.allInstance()->any(c|c.CardID=self.InputCard.CardIDandc.Password=self.InputCard.Password)",
    }).build().pass;
    let resultAmount: number = l()
      .if({
        logic: () =>
          l({
            logic: () => this.IsDeposit,
            description: "self.IsDeposit",
          }),
        description: "self.IsDeposit",
        then: l({
          logic: () => this.DepositedNumber,
          description: "self.DepositedNumber",
        }),
        else: l({
          logic: () => 0,
          description: "0",
        }),
      })
      .build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => this.CardIDValidated,
        description: "self.CardIDValidated",
      })
        .and({
          logic: () => this.PasswordValidated,
          description: "self.PasswordValidated",
        })
        .and({
          logic: () => getRepository(BankCard).includes(selectedCard),
          description: "BankCard.allInstance()->includes(selectedCard)",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

